51	static const char *wifi_manager_config_state_name(
52	  enum wifi_config_state_e state)
53	{
54	  switch (state)
55	    {
56	      case WIFI_CONFIG_STATE_MISSING:
57	        return "missing";
58	      case WIFI_CONFIG_STATE_INVALID:
59	        return "invalid";
60	      case WIFI_CONFIG_STATE_VALID:
61	        return "valid";
62	      default:
63	        return "unknown";
64	    }
65	}
