67	static void wifi_manager_publish_status(enum wifi_config_state_e state,
68	                                        bool associated, bool ipv4_ready,
69	                                        FAR const char *stage, int error,
70	                                        unsigned int retry_wait)
71	{
72	  char temporary[sizeof(WIFI_MANAGER_STATUS_PATH) + 8];
73	  char address[INET_ADDRSTRLEN];
74	  char data[512];
75	  struct in_addr ipv4;
76	  int fd;
77	  int length;
78	
79	  memset(&ipv4, 0, sizeof(ipv4));
80	  memset(address, 0, sizeof(address));
81	  if (ipv4_ready && netlib_get_ipv4addr(WIFI_MANAGER_INTERFACE, &ipv4) == 0)
82	    {
83	      inet_ntop(AF_INET, &ipv4, address, sizeof(address));
84	    }
85	
86	  length = snprintf(data, sizeof(data),
87	                    "{\"schema\":1,\"config\":\"%s\",\"associated\":%u,\"ipv4_ready\":%u,\"ipv4\":\"%s\",\"stage\":\"%s\",\"error\":%d,\"retry_wait\":%u}\n",
88	                    wifi_manager_config_state_name(state), associated ? 1 : 0,
89	                    ipv4_ready ? 1 : 0, address,
90	                    stage == NULL ? "" : stage, error, retry_wait);
91	  if (length < 0 || (size_t)length >= sizeof(data))
92	    {
93	      return;
94	    }
95	
96	  snprintf(temporary, sizeof(temporary), "%s.tmp", WIFI_MANAGER_STATUS_PATH);
97	  fd = open(temporary, O_WRONLY | O_CREAT | O_TRUNC, 0600);
98	  if (fd < 0)
99	    {
100	      return;
101	    }
102	
103	  if (write(fd, data, length) != length || fsync(fd) < 0)
104	    {
105	      close(fd);
106	      unlink(temporary);
107	      return;
108	    }
109	
110	  close(fd);
111	  rename(temporary, WIFI_MANAGER_STATUS_PATH);
112	}
