132	static int wifi_manager_read_config(struct wifi_config_s *config)
133	{
134	  char data[WIFI_CONFIG_FILE_MAX + 1];
135	  ssize_t length;
136	  int fd;
137	  int ret;
138	
139	  fd = open(WIFI_MANAGER_CONFIG_PATH, O_RDONLY);
140	  if (fd < 0)
141	    {
142	      return errno == ENOENT ? -ENOENT : -errno;
143	    }
144	
145	  length = read(fd, data, sizeof(data));
146	  if (length < 0)
147	    {
148	      ret = -errno;
149	      close(fd);
150	      return ret;
151	    }
152	
153	  ret = close(fd);
154	  if (ret < 0)
155	    {
156	      return -errno;
157	    }
158	
159	  if (length == sizeof(data))
