240	static int wifi_manager_connect(FAR const struct wifi_config_s *config,
241	                                FAR struct wifi_connect_result_s *result)
242	{
243	  int socket_fd;
244	  int ret;
245	  int retry;
246	
247	  result->stage = NULL;
248	  result->error = OK;
249	
250	  errno = 0;
251	  ret = netlib_ifup(WIFI_MANAGER_INTERFACE);
252	  if (ret < 0)
253	    {
254	      result->stage = WIFI_MANAGER_STAGE_IFUP;
255	      result->error = wifi_manager_normalize_error(ret);
256	      return result->error;
257	    }
258	
259	  errno = 0;
260	  socket_fd = wapi_make_socket();
261	  if (socket_fd < 0)
262	    {
263	      result->stage = WIFI_MANAGER_STAGE_SOCKET;
264	      result->error = wifi_manager_normalize_error(socket_fd);
265	      return result->error;
266	    }
267	
268	  ret = wapi_set_mode(socket_fd, WIFI_MANAGER_INTERFACE,
269	                      WAPI_MODE_MANAGED);
270	  if (ret < 0)
271	    {
272	      result->stage = WIFI_MANAGER_STAGE_MODE;
273	      goto out;
274	    }
275	
276	  ret = wpa_driver_wext_set_auth_param(socket_fd,
277	                                       WIFI_MANAGER_INTERFACE,
278	                                       IW_AUTH_WPA_VERSION,
279	                                       IW_AUTH_WPA_VERSION_WPA2);
280	  if (ret < 0)
281	    {
282	      result->stage = WIFI_MANAGER_STAGE_AUTH;
283	      goto out;
284	    }
285	
286	  ret = wpa_driver_wext_set_auth_param(socket_fd,
287	                                       WIFI_MANAGER_INTERFACE,
288	                                       IW_AUTH_CIPHER_PAIRWISE,
289	                                       IW_AUTH_CIPHER_CCMP);
290	  if (ret < 0)
291	    {
292	      result->stage = WIFI_MANAGER_STAGE_AUTH;
293	      goto out;
294	    }
295	
296	  ret = wpa_driver_wext_set_key_ext(socket_fd, WIFI_MANAGER_INTERFACE,
297	                                    WPA_ALG_CCMP, config->password,
298	                                    strlen(config->password));
299	  if (ret < 0)
300	    {
301	      result->stage = WIFI_MANAGER_STAGE_KEY;
302	      goto out;
303	    }
304	
305	  ret = wapi_set_essid(socket_fd, WIFI_MANAGER_INTERFACE, config->ssid,
306	                       WAPI_ESSID_ON);
307	  if (ret < 0)
308	    {
309	      result->stage = WIFI_MANAGER_STAGE_ESSID;
310	      goto out;
311	    }
312	
313	  ret = -ETIMEDOUT;
314	  result->stage = WIFI_MANAGER_STAGE_ASSOC;
315	  for (retry = 0; retry < WIFI_MANAGER_ASSOC_RETRIES; retry++)
316	    {
317	      if (wifi_manager_ap_connected(socket_fd))
318	        {
319	          ret = OK;
320	          break;
321	        }
322	
323	      sleep(1);
324	    }
325	
326	out:
327	  close(socket_fd);
328	  if (ret < 0)
329	    {
330	      result->error = wifi_manager_normalize_error(ret);
331	      return result->error;
332	    }
333	
334	  return wifi_manager_dhcp(result);
335	}
