337	int main(int argc, FAR char *argv[])
338	{
339	  struct wifi_config_s active_config;
340	  struct wifi_config_s pending_config;
341	  struct wifi_connect_result_s result;
342	  enum wifi_config_state_e state = WIFI_CONFIG_STATE_UNKNOWN;
343	  FAR const char *last_failure_stage = NULL;
344	  unsigned int backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
345	  unsigned int retry_wait = 0;
346	  int last_failure = OK;
347	  int socket_fd;
348	  int ret;
349	  bool active_valid = false;
350	  bool associated;
351	
352	  memset(&active_config, 0, sizeof(active_config));
353	  memset(&pending_config, 0, sizeof(pending_config));
354	  syslog(LOG_INFO, "wifi_manager: waiting for Wi-Fi configuration\n");
355	  wifi_manager_publish_status(WIFI_CONFIG_STATE_UNKNOWN, false, false,
356	                              NULL, 0, 0);
357	
358	  for (;;)
359	    {
360	      ret = wifi_manager_read_config(&pending_config);
361	      if (ret == -ENOENT)
362	        {
363	          if (state != WIFI_CONFIG_STATE_MISSING)
364	            {
365	              syslog(LOG_INFO,
366	                     "wifi_manager: configuration not present; idle\n");
367	            }
368	
369	          state = WIFI_CONFIG_STATE_MISSING;
370	          wifi_config_clear(&pending_config);
371	          wifi_config_clear(&active_config);
372	          active_valid = false;
373	          retry_wait = 0;
374	          last_failure = OK;
375	          last_failure_stage = NULL;
376	          wifi_manager_publish_status(state, false, false, NULL, 0, 0);
377	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
378	          continue;
379	        }
380	      else if (ret < 0)
381	        {
382	          if (state != WIFI_CONFIG_STATE_INVALID)
383	            {
384	              syslog(LOG_WARNING,
385	                     "wifi_manager: configuration is invalid; idle\n");
386	            }
387	
388	          state = WIFI_CONFIG_STATE_INVALID;
389	          wifi_config_clear(&pending_config);
390	          wifi_config_clear(&active_config);
391	          active_valid = false;
392	          retry_wait = 0;
393	          wifi_manager_publish_status(state, false, false, NULL, ret, 0);
394	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
395	          continue;
396	        }
397	
398	      state = WIFI_CONFIG_STATE_VALID;
399	      if (!active_valid ||
400	          !wifi_config_equal(&pending_config, &active_config))
401	        {
402	          wifi_config_clear(&active_config);
403	          active_config = pending_config;
404	          memset(&pending_config, 0, sizeof(pending_config));
405	          active_valid = true;
406	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
407	          retry_wait = 0;
408	          last_failure = OK;
409	          last_failure_stage = NULL;
410	          syslog(LOG_INFO, "wifi_manager: applying new configuration\n");
411	        }
412	      else
413	        {
414	          wifi_config_clear(&pending_config);
415	        }
416	
417	      if (retry_wait > 0)
418	        {
419	          retry_wait = retry_wait > WIFI_MANAGER_CONFIG_POLL_SEC ?
420	                       retry_wait - WIFI_MANAGER_CONFIG_POLL_SEC : 0;
421	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
422	          continue;
423	        }
424	
425	      socket_fd = wapi_make_socket();
426	      associated = socket_fd >= 0 &&
427	                   wifi_manager_ap_connected(socket_fd);
428	      if (socket_fd >= 0)
429	        {
430	          close(socket_fd);
431	        }
432	
433	      if (associated && wifi_manager_ipv4_ready())
434	        {
435	          wifi_manager_start_ntp();
436	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
437	          last_failure = OK;
438	          last_failure_stage = NULL;
439	          wifi_manager_publish_status(state, true, true, NULL, 0, 0);
440	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
441	          continue;
442	        }
443	
444	      if (associated)
445	        {
446	          ret = wifi_manager_dhcp(&result);
447	        }
448	      else
449	        {
450	          ret = wifi_manager_connect(&active_config, &result);
451	        }
452	
453	      if (ret == 0)
454	        {
455	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
456	          last_failure = OK;
457	          last_failure_stage = NULL;
458	          syslog(LOG_INFO, "wifi_manager: connected\n");
459	          if (wifi_manager_ipv4_ready())
460	            {
461	              wifi_manager_start_ntp();
462	            }
463	
464	          wifi_manager_publish_status(state, true, wifi_manager_ipv4_ready(),
465	                                      NULL, 0, 0);
466	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
467	          continue;
468	        }
469	
470	      if (ret != last_failure || result.stage != last_failure_stage)
471	        {
472	          syslog(LOG_WARNING,
473	                 "wifi_manager: %s failed (%d); retry in %u seconds\n",
474	                 result.stage == NULL ? "connection" : result.stage,
475	                 ret, backoff);
476	          last_failure = ret;
477	          last_failure_stage = result.stage;
478	        }
479	
480	      retry_wait = backoff;
481	      wifi_manager_publish_status(state, associated, false, result.stage,
482	                                  ret, retry_wait);
483	      if (backoff < WIFI_MANAGER_BACKOFF_MAX_SEC)
484	        {
485	          backoff *= 2;
486	          if (backoff > WIFI_MANAGER_BACKOFF_MAX_SEC)
487	            {
488	              backoff = WIFI_MANAGER_BACKOFF_MAX_SEC;
489	            }
490	        }
491	    }
492	
493	  return 0;
494	}
