29	static int wifi_config_decode_value(const char *value, size_t length,
30	                                    char *output, size_t output_size,
31	                                    size_t *decoded_length)
32	{
33	  size_t input_index = 0;
34	  size_t output_index = 0;
35	  bool quoted = false;
36	
37	  while (input_index < length &&
38	         (value[input_index] == ' ' || value[input_index] == '\t'))
39	    {
40	      input_index++;
41	    }
42	
43	  while (length > input_index &&
44	         (value[length - 1] == ' ' || value[length - 1] == '\t'))
45	    {
46	      length--;
47	    }
48	
49	  if (input_index < length && value[input_index] == '"')
50	    {
51	      quoted = true;
52	      input_index++;
53	    }
54	
55	  while (input_index < length)
56	    {
57	      char character = value[input_index++];
58	
59	      if (quoted && character == '"')
60	        {
61	          while (input_index < length &&
62	                 (value[input_index] == ' ' ||
63	                  value[input_index] == '\t'))
64	            {
65	              input_index++;
66	            }
67	
68	          if (input_index != length)
69	            {
70	              return -EINVAL;
71	            }
72	
73	          quoted = false;
74	          break;
75	        }
76	
77	      if (quoted && character == '\\')
78	        {
79	          if (input_index >= length)
80	            {
81	              return -EINVAL;
82	            }
83	
84	          character = value[input_index++];
85	          if (character != '\\' && character != '"')
86	            {
87	              return -EINVAL;
88	            }
89	        }
90	
91	      if (wifi_config_control_char(character) ||
92	          output_index + 1 >= output_size)
93	        {
94	          return -E2BIG;
95	        }
96	
97	      output[output_index++] = character;
98	    }
99	
100	  if (quoted)
101	    {
102	      return -EINVAL;
103	    }
104	
105	  output[output_index] = '\0';
106	  *decoded_length = output_index;
107	  return 0;
108	}
