110	static int wifi_config_parse_line(const char *line, size_t length,
111	                                  struct wifi_config_s *candidate,
112	                                  bool *ssid_found,
113	                                  bool *password_found)
114	{
115	  char *destination;
116	  size_t destination_size;
117	  size_t decoded_length;
118	  size_t key_length;
119	  int ret;
120	
121	  while (length > 0 && (*line == ' ' || *line == '\t'))
122	    {
123	      line++;
124	      length--;
125	    }
126	
127	  while (length > 0 &&
128	         (line[length - 1] == ' ' || line[length - 1] == '\t'))
129	    {
130	      length--;
131	    }
132	
133	  if (length == 0 || line[0] == '#')
134	    {
135	      return 0;
136	    }
137	
138	  if (length > 5 && memcmp(line, "SSID=", 5) == 0)
139	    {
140	      if (*ssid_found)
141	        {
142	          return -EINVAL;
143	        }
144	
145	      key_length = 5;
146	      destination = candidate->ssid;
147	      destination_size = sizeof(candidate->ssid);
148	      *ssid_found = true;
149	    }
150	  else if (length > 9 && memcmp(line, "PASSWORD=", 9) == 0)
151	    {
152	      if (*password_found)
153	        {
154	          return -EINVAL;
155	        }
156	
157	      key_length = 9;
158	      destination = candidate->password;
159	      destination_size = sizeof(candidate->password);
160	      *password_found = true;
161	    }
162	  else
163	    {
164	      return -EINVAL;
165	    }
166	
167	  ret = wifi_config_decode_value(line + key_length, length - key_length,
168	                                 destination, destination_size,
169	                                 &decoded_length);
170	  if (ret < 0)
171	    {
172	      return ret;
173	    }
174	
175	  if (destination == candidate->ssid)
176	    {
177	      if (decoded_length == 0 || decoded_length > WIFI_CONFIG_SSID_MAX)
178	        {
179	          return -EINVAL;
180	        }
181	    }
182	  else if (decoded_length < WIFI_CONFIG_PASSWORD_MIN ||
183	           decoded_length > WIFI_CONFIG_PASSWORD_MAX)
184	    {
185	      return -EINVAL;
186	    }
187	
188	  return 0;
189	}
