191	int wifi_config_parse(const char *data, size_t length,
192	                      struct wifi_config_s *config)
193	{
194	  struct wifi_config_s candidate;
195	  bool ssid_found = false;
196	  bool password_found = false;
197	  size_t line_start = 0;
198	  size_t index;
199	  int ret = 0;
200	
201	  if (data == NULL || config == NULL || length == 0 ||
202	      length > WIFI_CONFIG_FILE_MAX)
203	    {
204	      return -EINVAL;
205	    }
206	
207	  memset(&candidate, 0, sizeof(candidate));
208	
209	  for (index = 0; index <= length; index++)
210	    {
211	      if (index < length && data[index] == '\0')
212	        {
213	          ret = -EINVAL;
214	          goto out;
215	        }
216	
217	      if (index == length || data[index] == '\n')
218	        {
219	          size_t line_length = index - line_start;
220	
221	          if (line_length > 0 && data[line_start + line_length - 1] == '\r')
222	            {
223	              line_length--;
224	            }
225	
226	          ret = wifi_config_parse_line(data + line_start, line_length,
227	                                       &candidate, &ssid_found,
228	                                       &password_found);
229	          if (ret < 0)
230	            {
231	              goto out;
232	            }
233	
234	          line_start = index + 1;
235	        }
236	    }
237	
238	  if (!ssid_found || !password_found)
239	    {
240	      ret = -EINVAL;
241	      goto out;
242	    }
243	
244	  *config = candidate;
245	  wifi_config_wipe(&candidate, sizeof(candidate));
246	  return 0;
247	
248	out:
249	  wifi_config_wipe(&candidate, sizeof(candidate));
250	  return ret;
251	}
252	
253	void wifi_config_clear(struct wifi_config_s *config)
254	{
255	  if (config != NULL)
256	    {
257	      wifi_config_wipe(config, sizeof(*config));
258	    }
259	}
260	
261	int wifi_config_equal(const struct wifi_config_s *left,
262	                      const struct wifi_config_s *right)
263	{
264	  if (left == NULL || right == NULL)
265	    {
266	      return 0;
267	    }
268	
269	  return strcmp(left->ssid, right->ssid) == 0 &&
270	         strcmp(left->password, right->password) == 0;
271	}
