185	      strchr(cursor, '/') != NULL)
186	    {
187	      return -EINVAL;
188	    }
189	  sample_length = extension - cursor;
190	  if (session_length == 0 || session_length > 32 || sample_length == 0 ||
191	      sample_length > 32)
192	    {
193	      return -EINVAL;
194	    }
195	
196	  memcpy(session, path + 12, session_length);
197	  session[session_length] = '\0';
198	  memcpy(sample, cursor, sample_length);
199	  sample[sample_length] = '\0';
200	  if (!lan_panel_safe_component(session, session_length) ||
201	      !lan_panel_safe_component(sample, sample_length))
