337	int main(int argc, FAR char *argv[])
338	{
339	  struct sockaddr_in address;
340	  struct sockaddr_in client;
341	  socklen_t client_length;
342	  char token[LAN_PANEL_TOKEN_MAX];
343	  int listensd;
344	  int acceptsd;
345	  int opt = 1;
346	  int ret;
347	
348	  (void)argc;
349	  (void)argv;
350	  signal(SIGINT, lan_panel_signal);
351	  signal(SIGTERM, lan_panel_signal);
352	
353	  ret = lan_auth_load(token, sizeof(token));
354	  if (ret < 0)
355	    {
356	      printf("lan_panel: authentication storage unavailable: %d\n", ret);
357	      return EXIT_FAILURE;
358	    }
359	  printf("lan_panel: bootstrap token=%s\n", token);
360	
361	  listensd = socket(AF_INET, SOCK_STREAM, 0);
362	  if (listensd < 0)
363	    {
364	      return EXIT_FAILURE;
365	    }
366	  setsockopt(listensd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
367	  memset(&address, 0, sizeof(address));
368	  address.sin_family = AF_INET;
369	  address.sin_port = htons(CONFIG_CONTEST2026_113_LAN_PANEL_PORT);
370	  address.sin_addr.s_addr = htonl(INADDR_ANY);
371	  if (bind(listensd, (struct sockaddr *)&address, sizeof(address)) < 0 ||
372	      listen(listensd, 1) < 0)
373	    {
374	      close(listensd);
375	      return EXIT_FAILURE;
376	    }
377	
378	  printf("lan_panel: listening on port %u\n",
379	         CONFIG_CONTEST2026_113_LAN_PANEL_PORT);
380	  while (!g_stop)
381	    {
382	      client_length = sizeof(client);
383	      acceptsd = accept(listensd, (struct sockaddr *)&client, &client_length);
384	      if (acceptsd < 0)
385	        {
386	          if (errno == EINTR)
387	            {
388	              continue;
389	            }
390	          break;
391	        }
392	      lan_panel_set_timeout(acceptsd);
393	      lan_panel_handle(acceptsd, token);
394	      close(acceptsd);
395	    }
396	
397	  close(listensd);
398	  memset(token, 0, sizeof(token));
399	  return EXIT_SUCCESS;
400	}
