1	/****************************************************************************
2	 * contest2026_113_veladuxingke/app/lan_panel/lan_auth.c
3	 ****************************************************************************/
4	
5	#include <nuttx/config.h>
6	
7	#include <errno.h>
8	#include <fcntl.h>
9	#include <stdio.h>
10	#include <string.h>
11	#include <sys/stat.h>
12	#include <unistd.h>
13	
14	#ifndef CONFIG_CONTEST2026_113_LAN_PANEL_AUTH_PATH
15	#  define CONFIG_CONTEST2026_113_LAN_PANEL_AUTH_PATH "/data/panel.auth"
16	#endif
17	
18	#define LAN_AUTH_BYTES 32
19	#define LAN_AUTH_TEXT (LAN_AUTH_BYTES * 2)
20	
21	static int lan_auth_hex(unsigned char value)
22	{
23	  return value < 10 ? '0' + value : 'a' + value - 10;
24	}
25	
26	static int lan_auth_read_random(unsigned char *data, size_t size)
27	{
28	  int fd = open("/dev/urandom", O_RDONLY);
29	  size_t offset = 0;
30	
31	  if (fd < 0)
32	    {
33	      return -errno;
34	    }
35	
36	  while (offset < size)
37	    {
38	      ssize_t length = read(fd, data + offset, size - offset);
39	      if (length <= 0)
40	        {
41	          int ret = length == 0 ? -EIO : -errno;
42	          close(fd);
43	          return ret;
44	        }
45	      offset += length;
46	    }
47	
48	  close(fd);
49	  return 0;
50	}
51	
52	static int lan_auth_load_file(char *token, size_t size)
53	{
54	  int fd;
55	  ssize_t length;
56	
57	  fd = open(CONFIG_CONTEST2026_113_LAN_PANEL_AUTH_PATH, O_RDONLY);
58	  if (fd < 0)
59	    {
60	      return -errno;
61	    }
62	
63	  length = read(fd, token, size - 1);
64	  close(fd);
65	  if (length != LAN_AUTH_TEXT)
66	    {
67	      return -EINVAL;
68	    }
69	
70	  token[length] = '\0';
71	  return 0;
72	}
73	
74	int lan_auth_load(char *token, size_t size)
75	{
76	  unsigned char random_bytes[LAN_AUTH_BYTES];
77	  char temporary[sizeof(CONFIG_CONTEST2026_113_LAN_PANEL_AUTH_PATH) + 8];
78	  char generated[LAN_AUTH_TEXT + 1];
79	  int fd;
80	  int ret;
81	  size_t i;
82	
83	  if (token == NULL || size <= LAN_AUTH_TEXT)
84	    {
85	      return -EINVAL;
86	    }
87	
88	  ret = lan_auth_load_file(token, size);
89	  if (ret == 0)
90	    {
91	      return 0;
92	    }
93	
94	  ret = lan_auth_read_random(random_bytes, sizeof(random_bytes));
95	  if (ret < 0)
96	    {
97	      return ret;
98	    }
99	
100	  for (i = 0; i < sizeof(random_bytes); i++)
101	    {
102	      generated[i * 2] = lan_auth_hex(random_bytes[i] >> 4);
103	      generated[i * 2 + 1] = lan_auth_hex(random_bytes[i] & 0x0f);
104	    }
105	  generated[LAN_AUTH_TEXT] = '\0';
106	
107	  snprintf(temporary, sizeof(temporary), "%s.tmp",
108	           CONFIG_CONTEST2026_113_LAN_PANEL_AUTH_PATH);
109	  fd = open(temporary, O_WRONLY | O_CREAT | O_EXCL, 0600);
110	  if (fd < 0 && errno == EEXIST)
111	    {
112	      unlink(temporary);
113	      fd = open(temporary, O_WRONLY | O_CREAT | O_EXCL, 0600);
114	    }
115	  if (fd < 0)
116	    {
117	      return -errno;
118	    }
119	
120	  ret = write(fd, generated, LAN_AUTH_TEXT) == LAN_AUTH_TEXT ? 0 : -EIO;
121	  if (ret == 0 && fsync(fd) < 0)
122	    {
123	      ret = -errno;
124	    }
125	  close(fd);
126	  if (ret < 0 || rename(temporary, CONFIG_CONTEST2026_113_LAN_PANEL_AUTH_PATH) < 0)
127	    {
128	      if (ret == 0)
129	        {
130	          ret = -errno;
131	        }
132	      unlink(temporary);
133	      return ret;
134	    }
135	
136	  memcpy(token, generated, sizeof(generated));
137	  memset(random_bytes, 0, sizeof(random_bytes));
138	  memset(generated, 0, sizeof(generated));
139	  return 0;
140	}
141	
142	int lan_auth_check(const char *token, size_t length)
143	{
144	  char expected[LAN_AUTH_TEXT + 1];
145	  size_t i;
146	  unsigned char difference = 0;
147	
148	  if (token == NULL || length != LAN_AUTH_TEXT ||
149	      lan_auth_load(expected, sizeof(expected)) < 0)
150	    {
151	      return -EACCES;
152	    }
153	
154	  for (i = 0; i < LAN_AUTH_TEXT; i++)
155	    {
156	      difference |= (unsigned char)(token[i] ^ expected[i]);
157	    }
158	
159	  memset(expected, 0, sizeof(expected));
160	  return difference == 0 ? 0 : -EACCES;
161	}
