1	/****************************************************************************
2	 * contest2026_113_veladuxingke/app/lan_panel/lan_http.c
3	 ****************************************************************************/
4	
5	#include <nuttx/config.h>
6	
7	#include <errno.h>
8	#include <fcntl.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <strings.h>
12	#include <string.h>
13	#include <sys/stat.h>
14	#include <sys/socket.h>
15	#include <unistd.h>
16	
17	#include "lan_http.h"
18	
19	#define LAN_HTTP_MAX_HEADERS 4096
20	#define LAN_HTTP_CHUNK 4096
21	
22	static ssize_t lan_http_read_some(int fd, char *buffer, size_t size)
23	{
24	  ssize_t length = recv(fd, buffer, size, 0);
25	  return length < 0 ? -errno : length;
26	}
27	
28	static int lan_http_send_all(int fd, const char *data, size_t length)
29	{
30	  while (length > 0)
31	    {
32	      ssize_t sent = send(fd, data, length, 0);
33	      if (sent <= 0)
34	        {
35	          return sent == 0 ? -EPIPE : -errno;
36	        }
37	      data += sent;
38	      length -= sent;
39	    }
40	
41	  return 0;
42	}
43	
44	static char *lan_http_find_header_end(char *data, size_t length)
45	{
46	  size_t i;
47	
48	  for (i = 3; i < length; i++)
49	    {
50	      if (data[i - 3] == '\r' && data[i - 2] == '\n' &&
51	          data[i - 1] == '\r' && data[i] == '\n')
52	        {
53	          return data + i + 1;
54	        }
55	    }
56	
57	  return NULL;
58	}
59	
60	static int lan_http_header_value(char *headers, const char *name,
61	                                 char **value)
62	{
63	  char *line = headers;
64	  size_t name_length = strlen(name);
65	
66	  while (*line != '\0')
67	    {
68	      char *end = strstr(line, "\r\n");
69	      if (end == NULL)
70	        {
71	          return -EINVAL;
72	        }
73	      *end = '\0';
74	      if (strncasecmp(line, name, name_length) == 0 &&
75	          line[name_length] == ':')
76	        {
77	          char *cursor = line + name_length + 1;
78	          while (*cursor == ' ' || *cursor == '\t')
79	            {
80	              cursor++;
81	            }
82	          *value = cursor;
83	          return 0;
84	        }
85	      line = end + 2;
86	    }
87	
88	  return -ENOENT;
89	}
90	
91	int lan_http_read_request(int fd, struct lan_http_request_s *request)
92	{
93	  char buffer[LAN_HTTP_MAX_HEADERS + 1];
94	  char *header_end;
95	  char *line_end;
96	  char *content_length_text;
97	  size_t used = 0;
98	  size_t header_length;
99	  unsigned long content_length = 0;
100	  ssize_t length;
101	
102	  if (request == NULL)
103	    {
104	      return -EINVAL;
105	    }
106	  memset(request, 0, sizeof(*request));
107	
108	  while (used < LAN_HTTP_MAX_HEADERS)
109	    {
110	      length = lan_http_read_some(fd, buffer + used,
111	                                  LAN_HTTP_MAX_HEADERS - used);
112	      if (length <= 0)
113	        {
114	          return length == 0 ? -ECONNRESET : (int)length;
115	        }
116	      used += length;
117	      buffer[used] = '\0';
118	      header_end = lan_http_find_header_end(buffer, used);
119	      if (header_end != NULL)
120	        {
121	          break;
122	        }
123	    }
124	
125	  if (header_end == NULL)
126	    {
127	      return -E2BIG;
128	    }
129	
130	  line_end = strstr(buffer, "\r\n");
131	  if (line_end == NULL)
132	    {
133	      return -EINVAL;
134	    }
135	  *line_end = '\0';
136	  if (sscanf(buffer, "%7s %255s HTTP/1.%*1[01]", request->method,
137	             request->path) != 2)
138	    {
139	      return -EINVAL;
140	    }
141	
142	  header_length = (size_t)(header_end - (line_end + 2));
143	  (void)header_length;
144	  header_end[-2] = '\0';
145	  if (lan_http_header_value(line_end + 2, "Authorization",
146	                            &content_length_text) == 0)
147	    {
148	      strlcpy(request->authorization, content_length_text,
149	              sizeof(request->authorization));
150	    }
151	
152	  content_length_text = NULL;
153	  if (lan_http_header_value(line_end + 2, "Content-Length",
154	                            &content_length_text) == 0)
155	    {
156	      char *end;
157	      errno = 0;
158	      content_length = strtoul(content_length_text, &end, 10);
159	      if (errno != 0 || *end != '\0' || content_length > sizeof(request->body))
160	        {
161	          return -E2BIG;
162	        }
163	    }
164	
165	  if (content_length > 0)
166	    {
167	      size_t already = used - (size_t)(header_end - buffer);
168	      if (already > content_length)
169	        {
170	          return -EINVAL;
171	        }
172	      if (already > 0)
173	        {
174	          memcpy(request->body, header_end, already);
175	        }
176	      request->body_length = already;
177	      while (request->body_length < content_length)
178	        {
179	          length = lan_http_read_some(fd,
180	                                      request->body + request->body_length,
181	                                      content_length - request->body_length);
182	          if (length <= 0)
183	            {
184	              return length == 0 ? -ECONNRESET : (int)length;
185	            }
186	          request->body_length += length;
187	        }
188	    }
189	
190	  return 0;
191	}
192	
193	int lan_http_send_response(int fd, int status, const char *type,
194	                           const char *body, size_t length)
195	{
196	  char header[256];
197	  int header_length;
198	
199	  header_length = snprintf(header, sizeof(header),
200	                           "HTTP/1.0 %d\r\nContent-Type: %s\r\nContent-Length: %lu\r\nConnection: close\r\n\r\n",
201	                           status, type == NULL ? "text/plain" : type,
202	                           (unsigned long)length);
203	  if (header_length < 0 || (size_t)header_length >= sizeof(header))
204	    {
205	      return -E2BIG;
206	    }
207	
208	  if (lan_http_send_all(fd, header, header_length) < 0)
209	    {
210	      return -EPIPE;
211	    }
212	  return body == NULL || length == 0 ? 0 : lan_http_send_all(fd, body, length);
213	}
214	
215	int lan_http_send_file(int fd, const char *path, const char *type)
216	{
217	  char buffer[LAN_HTTP_CHUNK];
218	  struct stat info;
219	  int file;
220	  int ret;
221	  ssize_t length;
222	
223	  if (stat(path, &info) < 0 || !S_ISREG(info.st_mode))
224	    {
225	      return lan_http_send_response(fd, 404, "text/plain", "Not found\n", 10);
226	    }
227	
228	  {
229	    char header[256];
230	    int header_length = snprintf(header, sizeof(header),
231	                                 "HTTP/1.0 200\r\nContent-Type: %s\r\nContent-Length: %lu\r\nConnection: close\r\n\r\n",
232	                                 type == NULL ? "application/octet-stream" : type,
233	                                 (unsigned long)info.st_size);
234	    if (header_length < 0 || (size_t)header_length >= sizeof(header))
235	      {
236	        return -E2BIG;
237	      }
238	    ret = lan_http_send_all(fd, header, header_length);
239	    if (ret < 0)
240	      {
241	        return ret;
242	      }
243	  }
244	
245	  file = open(path, O_RDONLY);
246	  if (file < 0)
247	    {
248	      return -errno;
249	    }
250	  do
251	    {
252	      length = read(file, buffer, sizeof(buffer));
253	      if (length > 0)
254	        {
255	          ret = lan_http_send_all(fd, buffer, length);
256	        }
257	      else
258	        {
259	          ret = length < 0 ? -errno : 0;
260	        }
261	    }
262	  while (ret == 0 && length > 0);
263	
264	  close(file);
265	  return ret;
266	}
