130	/* 扫描 Wi-Fi 网络 */
131	static void wifi_ui_scan_networks(struct wifi_ui_context_s *ctx)
132	{
133	  int sockfd;
134	  int ret;
135	  int i;
136	  struct wapi_list_s list;
137	  struct wapi_scan_info_s *scan_info;
138	
139	  ctx->scanning = true;
140	  ctx->network_count = 0;
141	
142	  const char *msg = ctx->chinese ? "扫描中..." : "Scanning...";
143	  lv_label_set_text(ctx->status_label, msg);
144	  lv_obj_clear_flag(ctx->scan_list, LV_OBJ_FLAG_HIDDEN);
145	
146	  /* 清空列表 */
147	  lv_obj_clean(ctx->scan_list);
148	
149	  sockfd = socket(PF_INET, SOCK_DGRAM, 0);
150	  if (sockfd < 0)
151	    {
152	      msg = ctx->chinese ? "错误：无法打开套接字" : "Error: Cannot open socket";
153	      lv_label_set_text(ctx->status_label, msg);
154	      ctx->scanning = false;
155	      return;
156	    }
157	
158	  /* 初始化扫描 - NULL 表示扫描所有网络 */
159	  ret = wapi_scan_init(sockfd, WIFI_INTERFACE, NULL);
160	  if (ret < 0)
161	    {
162	      msg = ctx->chinese ? "错误：扫描初始化失败" : "Error: Scan init failed";
163	      lv_label_set_text(ctx->status_label, msg);
164	      close(sockfd);
165	      ctx->scanning = false;
166	      return;
167	    }
168	
169	  /* 等待扫描完成 */
170	  sleep(3);
171	
172	  /* 检查扫描状态 */
173	  ret = wapi_scan_stat(sockfd, WIFI_INTERFACE);
174	  if (ret < 0)
175	    {
176	      msg = ctx->chinese ? "错误：扫描失败" : "Error: Scan failed";
177	      lv_label_set_text(ctx->status_label, msg);
178	      close(sockfd);
179	      ctx->scanning = false;
180	      return;
181	    }
182	
183	  /* 获取扫描结果 */
184	  memset(&list, 0, sizeof(list));
185	  ret = wapi_scan_coll(sockfd, WIFI_INTERFACE, &list);
186	  close(sockfd);
187	
188	  if (ret < 0)
189	    {
190	      msg = ctx->chinese ? "错误：获取结果失败" : "Error: Get results failed";
191	      lv_label_set_text(ctx->status_label, msg);
192	      ctx->scanning = false;
193	      return;
194	    }
195	
196	  /* 解析结果 */
197	  scan_info = list.head.scan;
198	  while (scan_info != NULL && ctx->network_count < WIFI_UI_MAX_NETWORKS)
199	    {
200	      if (scan_info->essid[0] != '\0')
201	        {
202	          /* 检查是否已存在（去重） */
203	          bool duplicate = false;
204	          for (i = 0; i < ctx->network_count; i++)
205	            {
206	              if (strcmp(ctx->networks[i].ssid, scan_info->essid) == 0)
207	                {
208	                  duplicate = true;
209	                  break;
210	                }
211	            }
212	
213	          if (!duplicate)
214	            {
215	              strncpy(ctx->networks[ctx->network_count].ssid, scan_info->essid,
216	                      sizeof(ctx->networks[0].ssid) - 1);
217	              ctx->networks[ctx->network_count].ssid[sizeof(ctx->networks[0].ssid) - 1] = '\0';
218	              ctx->networks[ctx->network_count].rssi = scan_info->rssi;
219	              /* 假设有加密（安全起见） */
220	              ctx->networks[ctx->network_count].secured = true;
221	              ctx->network_count++;
222	            }
223	        }
224	
225	      scan_info = scan_info->next;
226	    }
227	
228	  /* 释放扫描结果 */
229	  wapi_scan_coll_free(&list);
230	
231	  /* 更新列表显示 */
232	  for (i = 0; i < ctx->network_count; i++)
233	    {
234	      lv_obj_t *btn = lv_list_add_button(ctx->scan_list, LV_SYMBOL_WIFI,
235	                                         ctx->networks[i].ssid);
236	      lv_obj_set_user_data(btn, (void *)(uintptr_t)i);
237	      lv_obj_add_event_cb(btn, wifi_ui_network_clicked, LV_EVENT_CLICKED, ctx);
238	
239	      /* 添加信号强度和加密标识 */
240	      lv_obj_t *label = lv_obj_get_child(btn, 1);
241	      if (label != NULL)
242	        {
243	          char buf[64];
244	          const char *lock_icon = ctx->networks[i].secured ? "🔒" : "";
245	          snprintf(buf, sizeof(buf), "%s  %s  %ddBm",
246	                   ctx->networks[i].ssid,
247	                   lock_icon,
248	                   ctx->networks[i].rssi);
249	          lv_label_set_text(label, buf);
250	          lv_obj_set_style_text_font(label, ctx->font, 0);
251	        }
252	    }
253	
254	  if (ctx->network_count == 0)
255	    {
256	      msg = ctx->chinese ? "未发现网络" : "No networks found";
257	      lv_label_set_text(ctx->status_label, msg);
258	    }
259	  else
260	    {
261	      char buf[64];
262	      if (ctx->chinese)
263	        {
264	          snprintf(buf, sizeof(buf), "发现 %d 个网络", ctx->network_count);
265	        }
266	      else
267	        {
268	          snprintf(buf, sizeof(buf), "Found %d networks", ctx->network_count);
269	        }
270	      lv_label_set_text(ctx->status_label, buf);
271	    }
272	
273	  ctx->scanning = false;
274	}
