340	  lv_label_set_text(title, ctx->chinese ? "Wi-Fi 配置" : "WiFi Setup");
341	  lv_obj_set_style_text_font(title, ctx->font, 0);
342	  lv_obj_set_style_text_color(title, lv_color_hex(0xf5f7f8), 0);
343	  lv_obj_align(title, LV_ALIGN_TOP_LEFT, 10, 5);
