345	  /* 关闭按钮 */
346	  lv_obj_t *close_btn = lv_button_create(panel);
347	  lv_obj_set_size(close_btn, 40, 30);
348	  lv_obj_align(close_btn, LV_ALIGN_TOP_RIGHT, -5, 5);
